<template>
  <AccountLayout bare><main class="customers-page">
    <header><div><h1>Customers</h1><p>Dashboard <b>›</b> Customers</p></div><div class="header-actions"><button class="btn btn-outline-primary">⚱ Filter</button><button class="btn btn-primary" disabled title="Customer form will be added in the next design update">＋ New Customer</button></div></header>
    <section class="customer-summary"><div><span>♙</span><small>Total Customers</small><strong>{{ summary.total_customers || 0 }}</strong></div><div><span>✓</span><small>Active Customers</small><strong class="green">{{ summary.active_customers || 0 }}</strong></div><div><span>!</span><small>Inactive Customers</small><strong class="red">{{ summary.inactive_customers || 0 }}</strong></div><div><span>$</span><small>Total Outstanding</small><strong>{{ money(summary.total_outstanding) }}</strong></div></section>
    <section class="customer-table card"><div class="table-controls"><input v-model="search" class="form-control" placeholder="Search customers…" /><select v-model="status" class="form-select"><option value="">All Status</option><option value="1">Active</option><option value="0">Inactive</option></select><select v-model="customerType" class="form-select"><option value="">All Customer Types</option><option>Residential</option><option>Commercial</option></select></div><div v-if="error" class="alert alert-danger m-3">{{ error }}</div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><input type="checkbox" disabled /></th><th>Customer Name</th><th>Customer ID</th><th>Phone</th><th>Email</th><th>Customer Type</th><th>Total Invoices</th><th>Total Outstanding</th><th>Current Balance</th><th>Status</th><th>View Profile</th><th>Actions</th></tr></thead><tbody><tr v-for="customer in customers" :key="customer.id"><td><input type="checkbox" /></td><td><span class="initial">{{ initials(customer.name) }}</span><b>{{ customer.name }}</b></td><td>{{ customer.customer_id }}</td><td>{{ customer.phone || '—' }}</td><td>{{ customer.email || '—' }}</td><td>{{ customer.customer_type }}</td><td>{{ customer.total_invoices }}</td><td class="outstanding">{{ money(customer.total_outstanding) }}</td><td>{{ money(customer.current_balance) }}</td><td><span class="status" :class="customer.status_active?'active':'inactive'">{{ customer.status_active?'Active':'Inactive' }}</span></td><td><button class="link-button" disabled title="Profile view will be added later">View Profile</button></td><td><button class="icon-button" disabled title="Actions will be added later">⋮</button></td></tr><tr v-if="!customers.length && !loading"><td colspan="12" class="text-center text-muted py-5">No customers found for this project.</td></tr></tbody></table></div><footer><span>Showing {{ customers.length }} customer{{ customers.length===1?'':'s' }}</span><span class="pagination">‹ <b>1</b> ›</span></footer></section>
    <section class="bottom-summary"><div><span>▤</span><small>Total Invoices</small><b>{{ invoiceTotal }}</b></div><div><span>▣</span><small>Total Outstanding</small><b class="red">{{ money(summary.total_outstanding) }}</b></div><div><span>▤</span><small>Average Balance</small><b>{{ money(averageBalance) }}</b></div><div><span>!</span><small>Inactive Customers</small><b>{{ summary.inactive_customers || 0 }}</b></div></section>
  </main></AccountLayout>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import client from '../api/client'
import AccountLayout from '../components/AccountLayout.vue'
const customers=ref([]),summary=ref({}),search=ref(''),status=ref(''),customerType=ref(''),error=ref(''),loading=ref(false)
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v||0));const initials=name=>(name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();const invoiceTotal=computed(()=>customers.value.reduce((n,c)=>n+Number(c.total_invoices||0),0));const averageBalance=computed(()=>customers.value.length?customers.value.reduce((n,c)=>n+Number(c.current_balance||0),0)/customers.value.length:0)
let debounce; const load=async()=>{loading.value=true;error.value='';try{const {data}=await client.get('/customers',{params:{search:search.value,status:status.value,customer_type:customerType.value}});customers.value=data.data;summary.value=data.summary}catch(e){error.value=e.response?.data?.message||'Unable to load customers.'}finally{loading.value=false}};watch([search,status,customerType],()=>{clearTimeout(debounce);debounce=setTimeout(load,250)});onMounted(load)
</script>
<style scoped>
