 solid #e6ebf8;font-size:.78rem;font-weight:600}.pagination{display:flex;gap:12px;align-items:center}.pagination b{background:#0757e9;color:#fff;border-radius:5px;padding:4px 9px}.bottom-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;background:#fff;border:1px solid #dfe7fa;border-radius:10px;margin-top:18px;padding:18px}.bottom-summary div{display:grid;grid-template-columns:42px 1fr}.bottom-summary b{font-size:1.15rem}@media(max-width:1000px){.customer-summary,.bottom-summary{grid-template-columns:repeat(2,1fr)}.customer-summary>div:nth-child(2){border-right:0}}@media(max-width:620px){.customers-page{padding:16px}.customers-page header{align-items:flex-start;gap:10px;flex-direction:column}.table-controls{flex-direction:column}.table-controls input,.table-controls select{max-width:none}.customer-summary,.bottom-summary{grid-template-columns:1fr}.customer-summary>div{border-right:0;border-bottom:1px solid #e5eafa}}
</style>
